<?php declare(strict_types=1); ?>
<div class="table-wrap"><table id="ledger"><caption class="sr-only">Church offering reports, allocations, confirmed amounts and payment status</caption><thead><tr><th>CHURCH / REFERENCE</th><th>PERIOD</th><th>TOTAL OFFERING · 100%</th><th>CHURCH RETAINS</th><th>AMOUNT TO PAY</th><th>CONFIRMED</th><th>STATUS</th></tr></thead><tbody><?php foreach($ledgerRows as $row): ?><tr data-status="<?= e($row['status']) ?>"><td data-label="Church / reference"><div class="parish-cell"><span class="parish-avatar">✧</span><div><strong><?= e($row['node_name']) ?></strong><small><?= e($row['payment_reference']) ?></small></div></div></td><td data-label="Service period"><?= e(date('M',mktime(0,0,0,(int)$row['period_month'],1))) ?> <?= (int)$row['period_year'] ?></td><td data-label="Total offering · 100%"><?= e(Money::display($row['gross_income'])) ?></td><td data-label="Church retains"><?= e(Money::display(Money::decimal(max(0,Money::cents($row['gross_income'])-Money::cents($row['provincial_levy_due']))))) ?></td><td data-label="Amount to pay"><?= e(Money::display($row['provincial_levy_due'])) ?></td><td data-label="Confirmed amount"><?= e(Money::display($row['amount_paid'])) ?></td><td data-label="Status"><span class="badge <?= e($row['status']) ?>">● <?= e(ucfirst($row['status'])) ?></span></td></tr><?php endforeach ?><?php if(!$ledgerRows): ?><tr><td colspan="7"><div class="empty"><span>⇄</span><h3>No remittances yet</h3><p>Submitted offerings appear here.</p></div></td></tr><?php endif ?></tbody></table></div>
